/**
 * Pure rule for when a workspace is read-only because its subscription is
 * not in good standing. Writes call `assertWorkspaceWritable` in the billing
 * service, which throws `WorkspaceLockedError` from the reason computed here.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only (${reason}).`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * `null` means the workspace is writable at `now`.
 *
 * No subscription row and `active` are writable. `past_due` is locked
 * immediately. A trial locks at its period end. A cancellation locks at
 * `cancelAt`, and a canceled row with no cancellation date is locked now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return reached(subscription.cancelAt, now) ? "canceled" : null;
    default: {
      const unreachable: never = subscription.status;
      return unreachable;
    }
  }
}

function reached(stamp: string, now: Date): boolean {
  return new Date(stamp).getTime() <= now.getTime();
}

